        match function {
            ComponentFn::Function(function) => {
                elements.tags = tag_symbols(self.scoping, |tags| {
                    tags.visit_formal_parameters(&function.params);
                    if let Some(body) = &function.body {
                        tags.visit_function_body(body);
                    }
